import csv,hashlib,io,json,math,statistics
R=Path.cwd();E=R/'experiments/M6-METROLOGY-001';AA=R/'experiments/EXP-009/bench-results/aa';H=R.parent.parent
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
load=lambda p:json.loads(Path(p).read_text())
def pearson(x,y):
 a=statistics.mean(x);b=statistics.mean(y);den=math.sqrt(sum((v-a)**2 for v in x)*sum((v-b)**2 for v in y));return sum((v-a)*(w-b) for v,w in zip(x,y))/den if den else None
def main():
 inputs=load(E/'inputs.json');pins=inputs['files']
 for path,want in pins.items():assert sha(R/path)==want,path
 journal=[json.loads(s) for s in (AA/'commands.jsonl').read_text().splitlines()];summary=load(AA/'summary.json');schedule=load(R/'experiments/EXP-009/bench-results/calibrate/aa-schedule.json');public=load(AA/'public-raw-manifest.json');assert len(journal)==len(schedule)==len(summary['rows'])==48 and len(summary['blocks'])==12
 stream_map={s['original']:s for s in public['streams']};assert len(stream_map)==96 and public['byte_identical'] is True
 records=[];raw_provenance={};previous=None
 for i,(command,item,old) in enumerate(zip(journal,schedule,summary['rows'])):
  assert i==item['index']==old['index'] and command['name']==f'{i:03d}'
  expected_n=[100000,1000000] if (i//8)%2==0 else [1000000,100000]
  assert item['block']==i//8 and item['size']==expected_n[(i%8)//4] and item['position']==i%4 and item['side']=='ABBA'[i%4] and item['seed']==1+(i//8)%3
  assert command['returncode']==0 and not command['timed_out'] and command['child_reaped'] and command['owned_group_empty'] and command['release_safe']
  start=datetime.fromisoformat(command['started_utc']);end=datetime.fromisoformat(command['finished_utc']);assert end>=start and (previous is None or start>=previous);previous=end
  stdout=None
  for channel,m in command['raw'].items():
   p=stream_map[m['path']];assert p['sha256']==m['sha256'] and p['bytes']==m['bytes'];path=R/p['public'];assert sha(path)==m['sha256'] and path.stat().st_size==m['bytes'];raw_provenance[p['public']]=m['sha256']
   if channel=='stdout':stdout=path.read_text()
   else:assert path.stat().st_size==0
  reader=csv.DictReader(io.StringIO(stdout));values=list(reader);assert len(values)==1 and None not in values[0];raw=values[0];assert raw==old['csv']
  for key,value in {'size':item['size'],'seed':item['seed'],'operations':item['operations'],'requested_ops':item['operations'],'member_bytes':16,'warmup_passes':1,'traversals':0}.items():assert int(raw[key])==value
  assert raw['case']=='lookup-hit' and all(old[k]==item[k] for k in item)
  wall=int(raw['elapsed_ns']);thread=int(raw['thread_elapsed_ns']);assert thread>0 and wall>=10000000
  row=dict(item,wall_ns=wall,thread_ns=thread,clock_residual_ns=wall-thread,tree_bytes=int(raw['tree_bytes']),checksum=raw['checksum'],cpu_start=int(raw['cpu_start']),cpu_end=int(raw['cpu_end']),warmup_ns=int(raw['warmup_elapsed_ns']),process_started_utc=command['started_utc'],process_finished_utc=command['finished_utc'],raw_csv=raw,stdout_sha256=sha(R/stream_map[command['raw']['stdout']['path']]['public']))
  row['endpoint_changed']=row['cpu_start']!=row['cpu_end'];row['wall_ns_per_query']=wall/row['operations'];row['thread_ns_per_query']=thread/row['operations'];records.append(row)
 assert len({r['command'][0] for r in journal})==1,'same-binary identity differs'
 blocks=[]
 for size in [100000,1000000]:
  for block in range(6):
   q=[r for r in records if r['size']==size and r['block']==block];assert len(q)==4 and [r['position'] for r in q]==[0,1,2,3]
   assert len({(r['operations'],r['checksum'],r['tree_bytes'],r['seed']) for r in q})==1
   a=q[0]['wall_ns']+q[3]['wall_ns'];b=q[1]['wall_ns']+q[2]['wall_ns'];ta=q[0]['thread_ns']+q[3]['thread_ns'];tb=q[1]['thread_ns']+q[2]['thread_ns']
   resid=(q[1]['clock_residual_ns']+q[2]['clock_residual_ns'])-(q[0]['clock_residual_ns']+q[3]['clock_residual_ns']);assert b-a==(tb-ta)+resid
   wallpass=abs(b-a)*100<=a;threadpass=abs(tb-ta)*100<=ta;original=next(s for s in summary['blocks'] if s['size']==size and s['block']==block)
   assert wallpass==original['qualified'] and a==original['baseline_elapsed_sum'] and b==original['paired_elapsed_sum']
   wm=statistics.mean(r['wall_ns'] for r in q);tm=statistics.mean(r['thread_ns'] for r in q)
   for r in q:r['wall_centered_pct_within_quad']=100*(r['wall_ns']/wm-1);r['thread_centered_pct_within_quad']=100*(r['thread_ns']/tm-1)
   blocks.append({'size':size,'block':block,'seed':q[0]['seed'],'wall_A_sum_ns':a,'wall_B_sum_ns':b,'thread_A_sum_ns':ta,'thread_B_sum_ns':tb,'wall_effect_pct':100*(b-a)/a,'thread_effect_pct_diagnostic_only':100*(tb-ta)/ta,'wall_gate_pass':wallpass,'thread_abs_contrast_within_one_percent':threadpass,'wall_contrast_ns':b-a,'thread_contrast_ns':tb-ta,'residual_contrast_ns':resid,'thread_contrast_over_wall_A_pct':100*(tb-ta)/a,'residual_contrast_over_wall_A_pct':100*resid/a,'endpoint_pairs':[[r['cpu_start'],r['cpu_end']] for r in q],'endpoint_change_count':sum(r['endpoint_changed'] for r in q),'warmup_min_ns':min(r['warmup_ns'] for r in q),'warmup_max_ns':max(r['warmup_ns'] for r in q),'row_indices':[r['index'] for r in q]})
 seed_repeats=[];positions=[];endpoint_groups=[];sizes=[]
 for size in [100000,1000000]:
  rs=[r for r in records if r['size']==size];bs=[b for b in blocks if b['size']==size]
  sizes.append({'size':size,'wall_pass_count':sum(b['wall_gate_pass'] for b in bs),'thread_contrast_within1percent_count':sum(b['thread_abs_contrast_within_one_percent'] for b in bs),'row_count':len(rs),'clock_residual_min_ns':min(r['clock_residual_ns'] for r in rs),'clock_residual_max_ns':max(r['clock_residual_ns'] for r in rs),'endpoint_changed_rows':sum(r['endpoint_changed'] for r in rs),'endpoint_same_rows':sum(not r['endpoint_changed'] for r in rs),'endpoint_pair_counts':{f'{a}->{b}':n for (a,b),n in sorted(Counter((r['cpu_start'],r['cpu_end']) for r in rs).items())},'wall_thread_pearson_descriptive':pearson([r['wall_ns'] for r in rs],[r['thread_ns'] for r in rs]),'warmup_wall_pearson_descriptive':pearson([r['warmup_ns'] for r in rs],[r['wall_ns'] for r in rs]),'warmup_thread_pearson_descriptive':pearson([r['warmup_ns'] for r in rs],[r['thread_ns'] for r in rs])})
  for seed in [1,2,3]:seed_repeats.append({'size':size,'seed':seed,'occurrences':[{'block':b['block'],'wall_effect_pct':b['wall_effect_pct'],'thread_effect_pct_diagnostic_only':b['thread_effect_pct_diagnostic_only']} for b in bs if b['seed']==seed]})
  for position in range(4):
   subset=[r for r in rs if r['position']==position];positions.append({'size':size,'position':position,'label':['A outer1','B inner1','B inner2','A outer2'][position],'n':len(subset),'mean_wall_centered_pct_within_quad':statistics.mean(r['wall_centered_pct_within_quad'] for r in subset),'mean_thread_centered_pct_within_quad':statistics.mean(r['thread_centered_pct_within_quad'] for r in subset),'endpoint_changed_rows':sum(r['endpoint_changed'] for r in subset)})
  for pair in sorted({(r['cpu_start'],r['cpu_end']) for r in rs}):
   subset=[r for r in rs if (r['cpu_start'],r['cpu_end'])==pair];endpoint_groups.append({'size':size,'start':pair[0],'end':pair[1],'n':len(subset),'row_indices':[r['index'] for r in subset],'mean_wall_ns_per_query':statistics.mean(r['wall_ns_per_query'] for r in subset),'mean_thread_ns_per_query':statistics.mean(r['thread_ns_per_query'] for r in subset),'mean_clock_residual_ns':statistics.mean(r['clock_residual_ns'] for r in subset),'warning':'Post-hoc unbalanced association; not CPU-type/residency/migration or causal evidence'})
 # Shared consultation is actual root stdio evidence, never represented as this worker's calls.
 consult_path=H/'scratch/cpu-perf-m6-metrology-20261019/consult-calls.jsonl';raw_calls=consult_path.read_text().splitlines();calls=[json.loads(x) for x in raw_calls];shared=[]
 for line,call in zip(raw_calls,calls):
  tool=call.get('params',{}).get('name',call['method']);response=call['response'];shared.append({'tool':tool,'started_utc':call['started_utc'],'finished_utc':call['finished_utc'],'parameters':call.get('params',{}).get('arguments',{}),'journal_line_sha256':hashlib.sha256(line.encode()).hexdigest(),'response_canonical_json_sha256':hashlib.sha256(json.dumps(response,sort_keys=True,separators=(',',':')).encode()).hexdigest()})
 assert {'library_status','ask','read_source'}<={x['tool'] for x in shared}
 histories={};history_text={}
 historical_harness=H/'experiments/OVERNIGHT-2026-10-17/HARNESS-003/README.md';histories['root-checkout:'+str(historical_harness.relative_to(H))]=sha(historical_harness)
 for name in ['012-contract-diagnostic/RESULTS.md','012-contract-diagnostic/PLAN.json','017-metrology-review/selection.md','023-neon-replication/RESULTS.md']:
  path=H/'experiments/NIGHT-EXPLORATION-001/runs/apple-m6-mini/20261019T013000Z'/name;histories['root-checkout:'+str(path.relative_to(H))]=sha(path);history_text[name]=path.read_text()
 failed=[b for b in blocks if not b['wall_gate_pass']];assert len(failed)==3 and all(not b['thread_abs_contrast_within_one_percent'] for b in failed)
 availability={'own_check_utc':'2026-10-19T11:33:43 UTC','own_actions':['Enumerated ALL_TOOLS for cpu-perf/library_status/check_evidence/server names:0 direct tools','Called list_mcp_resources: only codex_apps server exposed, no cpu-perf resource server'],'direct_exposure':'unavailable in this worker tool session','shared_transport':'root actual compatible local stdio consultation consumed; its successful calls are shared evidence, not this worker calls','own_library_status_or_ask_calls':0,'shared_calls':shared,'shared_journal_location':'ignored root scratch/cpu-perf-m6-metrology-20261019/consult-calls.jsonl','shared_journal_sha256':sha(consult_path),'server':'cpu-perf0.1.1; bundled wheel commit deb5a0bac467 (2026-10-05)','coverage':'Initial library_status0/287 indexed,0 passages; ask supplied no matched source passages. Root then live-read LLVM Benchmarking tips successfully. No retrieved passage defines Apple thread accounting or establishes a causal explanation.','source_used':'https://llvm.org/docs/Benchmarking.html','effect_on_decision':'Supports preserving noise/bias limits; no M4 benchmark numbers or unread-source claims adopted.'}
 report={'status':'OFFLINE RECONSTRUCTION PASS; original EXP009 PARK unchanged','participant':'/root/followup_proposal_b','backend':'Inherited Codex/GPT-6 family; exact serving model/token/currency costs unknown','lens':'Schedule/seed/ABBA positions/time ordering/CPU endpoint association','hypothesis':'Recorded descheduling alone sufficiently accounts for all3 failed 1M wall controls','diagnostic_result':'Recorded-clock diagnostic does not clear: all3 also exceed1percent using thread CPU contrasts. Clock brackets differ and no wrapper/accounting-error bound is measured; physical descheduling-only is not formally falsified or identified.','new_method_recommendation':'NONE: these post-hoc associations do not establish a distinct validated method or justify repeats/retuning','native_build_benchmark_profile_executions':0,'common_inputs_sha256':pins,'raw_public_streams_verified':96,'all48_rows_retained':True,'all12_blocks_reconstructed':True,'max_abs_wall_thread_contrast_gap_percentage_points':max(abs(b['wall_effect_pct']-b['thread_effect_pct_diagnostic_only']) for b in blocks),'unchanged_wall_qualification_counts':{str(s['size']):s['wall_pass_count'] for s in sizes},'sizes':sizes,'blocks':blocks,'seed_repetition':seed_repeats,'position_descriptors':positions,'cpu_endpoint_associations':endpoint_groups,'rows':records,'raw_provenance':raw_provenance,'availability_and_shared_MCP':availability,'historical_provenance_sha256':histories,'script_sha256':sha(__file__),'limits':['Thread time is a diagnostic, never a substitute acceptance clock. The original wall-based ±1percent/10ms requirements and all failed rows remain.','Thread bracket starts before wall start and ends after wall end. Wall-minus-thread is a signed clock residual, not exact off-CPU duration; fixed timer edges/accounting effects remain.','CPU endpoints are only two observations. Same endpoints do not exclude migration; changed endpoints do not measure residency duration or identify performance/efficiency core type.','Process UTC starts/finishes include setup/warmup/postvalidation, not absolute timer-window timestamps. Equally spaced measurement centers cannot be reconstructed.','Seed repetition changes temporal half and size-order position. Post-hoc correlation, sign patterns and unbalanced endpoint groups are descriptive, with six blocks per size and no independent held-out diagnostic confirmation.','No clock/counter evidence distinguishes DVFS, cache/TLB/layout, contention, thermal behavior or other on-CPU causes. Low noise would also not establish lack of bias.','No another-architecture pooling, data dropping, source change, new optimization count, revised threshold or native retry occurs.']}
 for path,want in pins.items():assert sha(R/path)==want
 for path,want in raw_provenance.items():assert sha(R/path)==want
 (E/'reviews/B.json').write_text(json.dumps(report,indent=2)+'\n')
 table='\n'.join(f"|{b['size']:,}|{b['block']+1}|{b['seed']}|{b['wall_effect_pct']:+.6f}%|{b['thread_effect_pct_diagnostic_only']:+.6f}%|{'pass' if b['wall_gate_pass'] else '**FAIL**'}|{'within' if b['thread_abs_contrast_within_one_percent'] else '**outside**'}|{b['residual_contrast_ns']/1e6:+.6f}|" for b in blocks)
 sizes_text='\n'.join(f"- {s['size']:,}: endpoint changes {s['endpoint_changed_rows']}/24; pair counts {s['endpoint_pair_counts']}; signed wall−thread residual {s['clock_residual_min_ns']/1e6:.6f}–{s['clock_residual_max_ns']/1e6:.6f}ms." for s in sizes)
 md=f'''# B — independent schedule and endpoint diagnostic\n\nAll 48 public raw CSV rows and 96 stdout/stderr streams reconstruct exactly against their journal/hash publication and frozen schedule. All 12 ABBA blocks and the original wall decisions agree: 100K 6/6, 1M 3/6. Source NONE and EXP009 PARK remain unchanged. No native benchmark/profile/build/source edit occurred. This is not an optimization population. Participant /root/followup_proposal_b; exact serving model/token/currency costs unknown.\n\nThe diagnostic hypothesis that descheduling alone sufficiently explains all three failed 1M wall controls is not supported. Each of those blocks also exceeds the same ±1% threshold when reconstructed from recorded thread CPU time. This recorded contrast diagnostic does not identify the physical cause. In particular it does not formally falsify physical descheduling-only without a measured wrapper/accounting-error bound. Thread CPU time never replaces the preregistered wall clock.\n\n|Members|Block|Seed|Wall contrast|Thread contrast (diagnostic)|Original wall gate|Thread±1%|Residual contrast ms|\n|---:|---:|---:|---:|---:|---|---|---:|\n{table}\n\nEach contrast uses the same four original rows, with outer positions 0+3 versus inner 1+2. The last column is the difference between inner and outer **sums** of signed wall−thread residuals. For failed 1M blocks 3/5/6, wall contrasts are −17.538/+12.683/+31.341ms; residual contrasts are −0.183208/+0.354667/+0.342167ms. These are paired-sum arithmetic decompositions, not causal fractions of descheduled time. The thread brackets surround slightly wider code than wall brackets, so residuals include clock-edge/accounting differences and cannot be read as exact off-CPU duration.\n\n## Repetition and temporal order\n\nAll six seeds/positions retain the original deterministic order, with size order alternating by block and seeds 1/2/3 repeated in blocks 4/5/6. For 1M, each first seed occurrence has a negative inner-pair contrast, while each repeat is positive. Seed 1 changes−0.614488→+0.841157%; seed 2−0.593165→+1.036273%; seed 3−1.414059→+2.567325%. The thread contrasts show the same sign reversals. A stable fixture/seed effect alone does not explain these repeated-seed differences. Time/context interactions remain possible.\n\nThis is a post-hoc pattern in six blocks, not a validated temporal mechanism. Repetition simultaneously changes temporal half and which size executes first. Position summaries and all raw rows are in B.json; averaging complementary contrasts would hide the very failed blocks and is not allowed. ABBA ideally cancels equally spaced linear drift, but process-start timestamps include construction/warmup/postvalidation and do not reveal equally spaced timer-window centers. No observed sign flip uniquely implies nonlinear drift, warmup insufficiency, DVFS or cache behavior.\n\n## CPU endpoint associations\n\n{sizes_text}\n\nBoth sizes observe only endpoints 6/7, with both unchanged and changed pairs represented across ABBA positions. B.json retains every position and pair stratum without dropping a row or pooling size-specific ns/query. The grouping is unbalanced and post-hoc. Endpoint equality does not establish no migration; endpoint difference says nothing about residence duration, frequency or CPU type. The same binary, fixture seed and outputs remain constant within each quad; endpoints were neither assigned nor randomized. Therefore the endpoint associations do not support a causal core-placement correction.\n\n## MCP availability and shared consultation\n\nOwn availability check at 11:33:43 UTC: no cpu-perf/library_status/check_evidence tool was exposed in ALL_TOOLS; list_mcp_resources exposed only codex_apps, no cpu-perf server. I consumed the **shared root consultation** explicitly permitted by docs/PERFORMANCE-MCP.md, not calls claimed as my own. Root's local stdio journal contains successful initialize,library_status,ask and read_source calls at 11:32:55–11:32:56 UTC. Server 0.1.1 uses bundled list commit deb5a0bac467. Initial coverage was 0/287 indexed and ask returned no source passage. Root subsequently retrieved the primary [LLVM benchmarking guidance](https://llvm.org/docs/Benchmarking.html), which states “low noise is required, but not sufficient.” That supports the bias limitation; it supplies no Apple-clock causal explanation. Full request inputs, actual response hashes and shared-journal identity are in B.json. No unread lead or M4 benchmark figure is treated as evidence for M6.\n\n## Method recommendation: NONE\n\nThe data do not justify a new corrective method now. Replacing wall acceptance with thread time fails even descriptively in the same three 1M blocks. More work, longer windows, warmup inflation, favorable endpoint filtering or complementary-block averaging is not an evidence-supported new protocol. EXP009 already targets 600ms windows;023's separate corrected scan controls failed at224–260ms;012 used 100M iterator items and three warmups yet retained failed controls. Those contracts are different and are context, not pooled measurements or proof that any knob cannot work.\n\nHARNESS-003 already introduced case-matched miss warmup over HARNESS-002, explicitly without proving precision or a hardware mechanism. EXP009 uses the already matched hit-query warmup; that is not a novel intervention. 017 already considered resident-worker/context controls and selected NONE because candidate/mutation/guard transfer and isolation were not concrete. Rebranding that unexecuted method now would not supply missing transfer evidence. The current offline result shows variation also in the recorded thread clock; different bracket coverage, accounting errors and physical causes remain unresolved, so it cannot select a cause. A future proposal needs distinct observable causal/context control, preserved wall-clock gates and candidate/guard transfer before any native launch; no such ready method follows from these retained endpoints alone.\n\nReproduce this offline report: `python3 experiments/M6-METROLOGY-001/analyze-b.py`. It imports no driver and spawns no child. All input/row hashes are rechecked after analysis. Historical context is read from the shared root checkout because the partial EXP009 worktree does not materialize those campaign files. No new peer review was read.\n'''
 (E/'reviews/B.md').write_text(md)
 print(json.dumps({'status':'offline raw reconstruction PASS','wall_counts':report['unchanged_wall_qualification_counts'],'thread_failures_in_failed_wall_blocks':sum(not b['thread_abs_contrast_within_one_percent'] for b in failed),'new_method':'NONE','rows':48,'blocks':12,'raw_streams':96}))
if __name__=='__main__':main()
